  ('mo-r-57-01-c1-interrogatory-answers', 'mo', 'sairnlaw_deadline_seed_missouri.json', 1, '{"count": {"direction": "forward", "unit": "calendar_days", "value": 30}, "domain": "civil-litigation", "effective_from": "2021-12-01", "effective_to": null, "jurisdiction": "mo", "service_completion": {"note": "Mo. R. Civ. P. 43.01(d): \"Service by facsimile transmission or electronic mail is complete upon transmission, except that a transmission made on a Saturday, Sunday, or legal holiday, or after 5:00 p.m. shall be complete on the next day that is not a Saturday, Sunday, or legal holiday.\" R. 103.08(a) states the same for service through the electronic filing system, expressly \"for the purposes of calculating the time for filing a response\". This moves the TRIGGER DATE, not the amount added, so a service_time is REQUIRED for these methods and the engine refuses outright without one -- unlike Virginia''s R. 1:7 refusal, which can still return a date computed without an extension. Mail is deliberately NOT governed: R. 43.01(d) says \"Service by mail is complete upon mailing\", full stop.", "standard": "mo_rule_43_01_d"}, "service_extension": {"add": 3, "applies_when": ["mail"], "note": "Mo. R. Civ. P. 44.01(d) adds three days for service BY MAIL ONLY: \"the notice or paper is served by mail three days shall be added to the prescribed period\". \"Added to the prescribed period\", so the days lengthen the period and one rollover runs at the end -- NOT the federal after-expiry order. ELECTRONIC SERVICE GETS NOTHING HERE, and that is not an omission: it is handled by the separate service_completion standard on this row, which moves the date the period runs from instead. Do not widen applies_when to email or e-filing by analogy to Massachusetts or Tennessee -- Missouri deliberately does the opposite.", "standard": "mo_rule_44_01_d", "unit": "calendar_days"}, "trigger_event": "service_of_interrogatories"}'::jsonb),
