  ('ok-12-2012-a2-answer-to-crossclaim', 'ok', 'sairnlaw_deadline_seed_oklahoma.json', 1, '{"count": {"direction": "forward", "unit": "calendar_days", "value": 20}, "domain": "civil-litigation", "effective_from": "2004-11-01", "effective_to": null, "jurisdiction": "ok", "service_extension": {"add": 3, "applies_when": ["mail", "third_party_commercial_carrier", "electronic"], "note": "§ 2006(D): three days for mail, THIRD-PARTY COMMERCIAL CARRIER or electronic means, added TO THE PRESCRIBED PERIOD. Electronic qualifies, unlike Nevada, West Virginia, New York and the federal rule. Oklahoma is the ONLY seeded jurisdiction naming third-party commercial carrier as its own category — Texas lists commercial delivery among its methods but extends for mail alone, so do not read the two across.", "order": "add_to_period", "standard": "ok_12_2006_d", "unit": "calendar_days"}, "trigger_event": "service_of_crossclaim"}'::jsonb),
