  ('va-r-4-11-admission-response', 'va', 'sairnlaw_deadline_seed_virginia.json', 1, '{"count": {"direction": "forward", "unit": "calendar_days", "value": 21}, "domain": "civil-litigation", "effective_from": "2021-03-01", "effective_to": null, "jurisdiction": "va", "service_extension": {"note": "Amount and unit come from the standard, not this row. Va. Sup. Ct. R. 1:7 adds NOTHING for manual delivery, facsimile, electronic mail or same-day commercial delivery completed at or before 5:00 p.m., ONE day for any of those completed after 5:00 p.m. but before midnight, ONE day for a paper placed with a commercial delivery service before midnight for next-day delivery, and THREE days for mail. Supply service_time as HH:MM in 24-hour form for the four clock-dependent methods -- without it the engine refuses the extension visibly rather than choosing between 0 and 1.", "standard": "va_rule_1_7"}, "trigger_event": "service_of_request_for_admission"}'::jsonb),
