  ('wv-rcp-6-d3-response-memorandum', 'wv', 'sairnlaw_deadline_seed_westvirginia.json', 1, '{"count": {"direction": "forward", "unit": "calendar_days", "value": 21}, "domain": "civil-litigation", "effective_from": "2025-01-01", "effective_to": null, "jurisdiction": "wv", "service_extension": {"add": 3, "applies_when": ["mail", "left_with_clerk"], "standard": "wv_rcp_6e", "unit": "calendar_days"}, "trigger_event": "service_of_the_motion"}'::jsonb)
),
licences as (
  select k.key, k.app_id, encode(digest(k.key,'sha256'),'hex') as h
  from public.license_keys k where k.app_id = 'sairnlaw'
),
live as (
  select l.key as licence, r.entry_id, r.data,
         (r.data - 'authority' - 'computation' - 'label' - 'rule_id' - 'source_url' - 'supersedes' - 'verified_by' - 'verified_on' - 'version') as compute
  from licences l
  join public.law_deadline_rules r on r.license_hash = l.h
),
-- EVERY (licence, seed rule) PAIR, not every seed rule. Joining expected
-- straight to live on rule_id alone cannot see "missing from licence A while
-- present on licence B" -- the expected row finds B, matches, and A's absence
-- never appears. Enumerating the pairs first is what makes MISSING detectable
-- per licence, which is the whole point of a load-state gate.
wanted as (
  select l.key as licence, x.rule_id, x.jurisdiction, x.seed_file,
         x.seed_version, x.compute
  from licences l cross join expected x
)
select
  coalesce(w.licence, v.licence)               as licence,
  coalesce(w.rule_id, v.entry_id)              as rule_id,
  w.seed_file,
  case
    when v.entry_id is null then 'MISSING -- seed rule never loaded onto this licence'
    when w.rule_id  is null then 'ORPHAN -- live row with no seed; content of unknown origin'
    else 'STALE -- live content differs from the seed'
  end                                          as verdict,
  w.seed_version,
  v.data ->> 'version'                         as live_version,
  jsonb_pretty(w.compute)                      as seed_compute,
  jsonb_pretty(v.compute)                      as live_compute
from wanted w
full outer join live v
  on v.licence = w.licence and v.entry_id = w.rule_id
where v.entry_id is null
   or w.rule_id  is null
   or v.compute is distinct from w.compute
order by 4, 1, 2;
